const D = { scale: 1, energy: .8, depth: .5, speed: 1, density: .5, hue: 210, x: .5, y: .5, style: 'depth-glow', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- static geometry: 16 vertices of the 4-cube, 32 edges ----
if (!S.verts) {
  const V = [];
  for (let m = 0; m < 16; m++) V.push([ (m&1)?1:-1, (m&2)?1:-1, (m&4)?1:-1, (m&8)?1:-1 ]);
  const E = [];
  for (let i = 0; i < 16; i++) for (let d = 0; d < 4; d++) { const j = i ^ (1 << d); if (j > i) E.push([i, j]); }
  S.verts = V; S.edges = E;
}
// ---- seed: rotation phase offsets + hue jitter (inline hash, no p5 random) ----
if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
  S.ph1 = fr(1) * 6.283; S.ph2 = fr(2) * 6.283; S.ph3 = fr(3) * 6.283; S.hoff = (fr(4) - .5) * 40;
}

const u = Math.min(width, height);
const cx = P.x * width, cy = P.y * height;
const R = u * 0.85 * P.scale;
const style = P.style;
const sec = K.section, hdrift = sec * 17;
const spd = P.speed;
// two independent incommensurate 4D rotation planes (+ a slow third tumble); audio on top of the clk floor
const a1 = K.t * 0.31 * spd + S.ph1 + A.bass * 0.6;
const a2 = K.t * 0.23 * spd + S.ph2 + A.lowmid * 0.5;
const a3 = K.t * 0.17 * spd + S.ph3;
const c1 = Math.cos(a1), s1 = Math.sin(a1), c2 = Math.cos(a2), s2 = Math.sin(a2), c3 = Math.cos(a3), s3 = Math.sin(a3);
const distW = 3.0 - P.depth * 1.3;   // 4D eye distance (smaller = more dramatic inside-out turn)
const distZ = 3.2;                    // 3D eye distance
const glow = 0.35 + P.energy * 1.0 + K.intensity * 0.25 + A.rms * 0.6;

function proj(v, sc) {
  let x = v[0] * sc, y = v[1] * sc, z = v[2] * sc, w = v[3] * sc;
  // rotate in (x,w) plane
  let nx = x * c1 - w * s1, nw = x * s1 + w * c1; x = nx; w = nw;
  // rotate in (y,z) plane
  let ny = y * c2 - z * s2, nz = y * s2 + z * c2; y = ny; z = nz;
  // slow tumble in (x,y) plane
  nx = x * c3 - y * s3; ny = x * s3 + y * c3; x = nx; y = ny;
  const k1 = 1 / (distW - w);        // 4D -> 3D perspective
  x *= k1; y *= k1; z *= k1;
  const k2 = 1 / (distZ - z);        // 3D -> 2D perspective
  return { X: cx + x * k2 * R, Y: cy + y * k2 * R, w: w, k: k2 };
}

// ---- background: toned ground so the frame carries luminance (not pure black) ----
let bgH, bgS, bgB;
if (style === 'blueprint') { bgH = 218; bgS = 78; bgB = 38 + Math.sin(K.t * 0.2) * 3; }
else if (style === 'ice')  { bgH = 205; bgS = 30; bgB = 15; }
else if (style === 'gold-chrome') { bgH = 28; bgS = 60; bgB = 12; }
else if (style === 'neon-wire') { bgH = (P.hue + 180) % 360; bgS = 55; bgB = 10; }
else { bgH = (P.hue + hdrift) % 360; bgS = 55; bgB = 13 + K.swell * 3; } // depth-glow
// opaque bg at default; lower alpha => translucent ground for VJ compositing (no hard clear)
if (P.alpha >= 100) background(bgH, bgS, bgB);
else { push(); noStroke(); fill(bgH, bgS, bgB, P.alpha); rect(0, 0, width, height); pop(); }

const additive = style !== 'blueprint';
if (additive) { push(); blendMode(ADD); }
// ambient central bloom lifts luminance + gives volumetric depth (partial, alpha<=35)
if (additive) {
  noStroke();
  const bh = style === 'gold-chrome' ? 42 : style === 'ice' ? 195 : (P.hue + hdrift) % 360;
  fill(bh, style === 'ice' ? 25 : 60, 100, (10 + glow * 8));
  ellipse(cx, cy, R * 1.7, R * 1.7);
  fill(bh, style === 'ice' ? 15 : 45, 100, (6 + glow * 5));
  ellipse(cx, cy, R * 2.8, R * 2.8);
}

const nest = 1 + Math.round(P.density * 2);   // 1..3 concentric tesseracts
const V = S.verts, E = S.edges;
const nodeR = u * 0.011 * (0.7 + P.energy);

for (let c = 0; c < nest; c++) {
  const sc = Math.pow(0.6, c);
  const pts = [];
  for (let i = 0; i < 16; i++) pts.push(proj(V[i], sc));
  const cd = 1 - c * 0.22;   // inner copies slightly dimmer
  // edges as two-pass glowing struts, hued by 4D depth (w)
  for (let e = 0; e < E.length; e++) {
    const p = pts[E[e][0]], q = pts[E[e][1]];
    const wAvg = (p.w + q.w) * 0.5;          // -~1.4..1.4
    const wn = (wAvg + 1.42) / 2.84;          // 0..1 depth
    let h, sa, br;
    if (style === 'neon-wire') { h = (P.hue + wn * 18) % 360; sa = 95; br = 100; }
    else if (style === 'gold-chrome') { h = 30 + wn * 22; sa = 55 + wn * 35; br = 55 + wn * 45; }
    else if (style === 'blueprint') { h = 205; sa = 22 + wn * 18; br = 92; }
    else if (style === 'ice') { h = 190 + wn * 24; sa = 22 + wn * 30; br = 78 + wn * 22; }
    else { h = (P.hue + S.hoff + wn * 150 + hdrift) % 360; sa = 78; br = 92 + wn * 8; } // depth-glow rainbow
    const near = 0.5 + Math.max(0, Math.min(1, (wn))) * 0.9; // nearer struts brighter/thicker
    if (style === 'blueprint') {
      stroke(h, sa, br, 62 * cd); strokeWeight(u * 0.0022);
      line(p.X, p.Y, q.X, q.Y);
    } else {
      // halo pass
      stroke(h, sa * 0.7, br, (10 + glow * 10) * cd);
      strokeWeight(u * (0.010 + 0.010 * near) * (0.6 + P.energy));
      line(p.X, p.Y, q.X, q.Y);
      // core pass
      stroke(h, sa * 0.5, 100, (40 + glow * 30) * cd);
      strokeWeight(u * (0.0018 + 0.0016 * near));
      line(p.X, p.Y, q.X, q.Y);
    }
  }
  // glowing nodes
  noStroke();
  for (let i = 0; i < 16; i++) {
    const pt = pts[i]; const wn = (pt.w + 1.42) / 2.84;
    let h;
    if (style === 'neon-wire') h = P.hue;
    else if (style === 'gold-chrome') h = 40 + wn * 15;
    else if (style === 'blueprint') h = 205;
    else if (style === 'ice') h = 195;
    else h = (P.hue + S.hoff + wn * 150 + hdrift) % 360;
    if (style === 'blueprint') { fill(h, 30, 96, 70 * cd); ellipse(pt.X, pt.Y, nodeR * 1.4, nodeR * 1.4); }
    else {
      fill(h, 30, 100, (30 + glow * 25) * cd); ellipse(pt.X, pt.Y, nodeR * (2.4 + wn * 2), nodeR * (2.4 + wn * 2));
      fill(h, 10, 100, (60 + glow * 30) * cd); ellipse(pt.X, pt.Y, nodeR * (0.9 + wn * 0.6), nodeR * (0.9 + wn * 0.6));
    }
  }
}

if (additive) { blendMode(BLEND); pop(); }
// audio treble sparkle on top (partial, never full-frame invert)
if (A.treble > 0.03) {
  push(); blendMode(ADD); noStroke();
  fill((P.hue + hdrift + 40) % 360, 20, 100, A.treble * 18);
  ellipse(cx, cy, R * 1.2, R * 1.2);
  blendMode(BLEND); pop();
}
